namespace sv_ba2c31a90b4a4c3e82fe9e24e1253be4.Client.Models;

public class Shipment
{
    public required string TrackingNumber { get; set; }
    public required string Status { get; set; }
    public required string Location { get; set; }
    public DateTimeOffset? EstimatedDelivery { get; set; }
    public List<StatusUpdate> StatusUpdates { get; set; } = [];
}

public class StatusUpdate
{
    public required string Description { get; set; }
    public required string Location { get; set; }
    public DateTimeOffset Timestamp { get; set; }
}

using sv_ba2c31a90b4a4c3e82fe9e24e1253be4.Client.Models;

namespace sv_ba2c31a90b4a4c3e82fe9e24e1253be4.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_ba2c31a90b4a4c3e82fe9e24e1253be4.Client.Models;

namespace sv_ba2c31a90b4a4c3e82fe9e24e1253be4.Client.Services;

public class HttpShipmentService(HttpClient httpClient) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await httpClient.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

using sv_ba2c31a90b4a4c3e82fe9e24e1253be4.Client.Models;
using sv_ba2c31a90b4a4c3e82fe9e24e1253be4.Client.Services;

namespace sv_ba2c31a90b4a4c3e82fe9e24e1253be4.Services;

public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> Shipments = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new Shipment
        {
            TrackingNumber = "TRK-1001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 22, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "New York, NY", Timestamp = new DateTimeOffset(2026, 6, 16, 9, 0, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Departed facility", Location = "New York, NY", Timestamp = new DateTimeOffset(2026, 6, 16, 14, 30, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Arrived at sorting center", Location = "Chicago, IL", Timestamp = new DateTimeOffset(2026, 6, 17, 6, 15, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "In transit to destination", Location = "Chicago, IL", Timestamp = new DateTimeOffset(2026, 6, 18, 8, 0, 0, TimeSpan.Zero) },
            ]
        },
        ["TRK-2002"] = new Shipment
        {
            TrackingNumber = "TRK-2002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 18, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "Seattle, WA", Timestamp = new DateTimeOffset(2026, 6, 14, 10, 0, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "In transit", Location = "Portland, OR", Timestamp = new DateTimeOffset(2026, 6, 15, 7, 45, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Out for delivery", Location = "San Francisco, CA", Timestamp = new DateTimeOffset(2026, 6, 17, 8, 30, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Delivered — left at front door", Location = "San Francisco, CA", Timestamp = new DateTimeOffset(2026, 6, 17, 14, 12, 0, TimeSpan.Zero) },
            ]
        },
        ["TRK-3003"] = new Shipment
        {
            TrackingNumber = "TRK-3003",
            Status = "Processing",
            Location = "Dallas, TX",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 25, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Label created", Location = "Dallas, TX", Timestamp = new DateTimeOffset(2026, 6, 18, 16, 0, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Awaiting carrier pickup", Location = "Dallas, TX", Timestamp = new DateTimeOffset(2026, 6, 18, 16, 5, 0, TimeSpan.Zero) },
            ]
        }
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);
        Shipments.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_ba2c31a90b4a4c3e82fe9e24e1253be4.Client.Models
@using sv_ba2c31a90b4a4c3e82fe9e24e1253be4.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (isLoading)
{
    <div class="card mt-4">
        <div class="card-body placeholder-glow">
            <h5 class="card-title">Tracking: @TrackingNumber</h5>
            <p><span class="placeholder col-4"></span></p>
            <p><span class="placeholder col-6"></span></p>
            <p><span class="placeholder col-3"></span></p>
            <p class="text-muted">Loading shipment details…</p>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger mt-4" role="alert">
        <h5 class="alert-heading">Something went wrong</h5>
        <p>@errorMessage</p>
        <button class="btn btn-outline-danger" @onclick="RetryAsync">Try again</button>
    </div>
}
else if (shipment is null)
{
    <div class="alert alert-warning mt-4" role="alert">
        <h5 class="alert-heading">Not found</h5>
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <div class="card mt-4">
        <div class="card-header">
            <h5 class="mb-0">Tracking: @shipment.TrackingNumber</h5>
        </div>
        <div class="card-body">
            <p><strong>Status:</strong> @shipment.Status</p>
            <p><strong>Location:</strong> @shipment.Location</p>
            @if (shipment.EstimatedDelivery.HasValue)
            {
                <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.Value.ToString("f")</p>
            }
        </div>
    </div>

    @if (shipment.StatusUpdates.Count > 0)
    {
        <h6 class="mt-4">Tracking History</h6>
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Date</th>
                    <th>Location</th>
                    <th>Description</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in shipment.StatusUpdates.OrderByDescending(u => u.Timestamp))
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Location</td>
                        <td>@update.Description</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

