+            @if (shipment.EstimatedDelivery.HasValue)
+            {
+                <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.Value.ToString("f")</p>
+            }
+        </div>
+    </div>
+
+    @if (shipment.StatusUpdates.Count > 0)
+    {
+        <h6 class="mt-4">Tracking History</h6>
+        <table class="table table-striped">
+            <thead>
+                <tr>
+                    <th>Date</th>
+                    <th>Location</th>
+                    <th>Description</th>
+                </tr>
+            </thead>
+            <tbody>
+                @foreach (var update in shipment.StatusUpdates.OrderByDescending(u => u.Timestamp))
+                {
+                    <tr>
+                        <td>@update.Timestamp.ToString("g")</td>
+                        <td>@update.Location</td>
+                        <td>@update.Description</td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    }
+}
+
+@code {
+    [Parameter]
+    public string TrackingNumber { get; set; } = default!;
+
+    private Shipment? shipment;
+    private bool isLoading;
+    private string? errorMessage;
+
+    private CancellationTokenSource? cts;
+    private string? loadedTrackingNumber;
+
+    protected override async Task OnParametersSetAsync()
+    {
+        if (string.Equals(TrackingNumber, loadedTrackingNumber, StringComparison.OrdinalIgnoreCase) && !isLoading)
+            return;
+
+        await LoadShipmentAsync();
+    }
+
+    private async Task LoadShipmentAsync()
+    {
+        // Cancel any in-flight request
+        await CancelPendingRequestAsync();
+
+        cts = new CancellationTokenSource();
+        var ct = cts.Token;
+
+        loadedTrackingNumber = TrackingNumber;
+        shipment = null;
+        errorMessage = null;
+        isLoading = true;
+
+        try
+        {
+            shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
+        }
+        catch (OperationCanceledException) when (ct.IsCancellationRequested)
+        {
+            // Navigation or disposal cancelled this request — nothing to show.
+            return;
+        }
+        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
+        {
+            Logger.LogError(ex, "Timeout fetching shipment {TrackingNumber}", TrackingNumber);
+            errorMessage = "The request timed out. The server may be busy — please try again.";
+        }
+        catch (TimeoutException ex)
+        {
+            Logger.LogError(ex, "Timeout fetching shipment {TrackingNumber}", TrackingNumber);
+            errorMessage = "The request timed out. The server may be busy — please try again.";
+        }
+        catch (HttpRequestException ex)
+        {
+            Logger.LogError(ex, "Network error fetching shipment {TrackingNumber}", TrackingNumber);
+            errorMessage = "A network error occurred while loading shipment details. Please check your connection and try again.";
+        }
+        catch (Exception ex)
+        {
+            Logger.LogError(ex, "Unexpected error fetching shipment {TrackingNumber}", TrackingNumber);
+            errorMessage = "An unexpected error occurred while loading shipment details. Please try again.";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task RetryAsync()
+    {
+        loadedTrackingNumber = null;
+        await LoadShipmentAsync();
+    }
+
+    private async Task CancelPendingRequestAsync()
+    {
+        if (cts is not null)
+        {
+            await cts.CancelAsync();
+            cts.Dispose();
+            cts = null;
+        }
+    }
+
+    public void Dispose()
+    {
+        cts?.Cancel();
+        cts?.Dispose();
+        cts = null;
+    }
+}
